    17→/// deployer contract. This is done by directly setting the code of the create2 deployer account
    18→/// prior to executing any transactions on the timestamp activation of the fork.
    19→pub(crate) fn ensure_create2_deployer<DB>(
    20→    chain_spec: impl OpHardforks,
