    28→    // previous block timestamp (heuristically, block time is not perfectly constant at 2s), and the
    29→    // chain is an optimism chain, then we need to force-deploy the create2 deployer contract.
    30→    if chain_spec.is_canyon_active_at_timestamp(timestamp)
    31→        && !chain_spec.is_canyon_active_at_timestamp(timestamp.saturating_sub(2))
    32→    {
