    34→        let acc = db.load_cache_account(CREATE_2_DEPLOYER_ADDR)?;
    35→
    36→        // Update the account info with the create2 deployer codehash and bytecode.
    37→        let mut acc_info = acc.account_info().unwrap_or_default();
    38→        acc_info.code_hash = CREATE_2_DEPLOYER_CODEHASH;
    39→        acc_info.code = Some(Bytecode::new_raw(Bytes::from_static(&CREATE_2_DEPLOYER_BYTECODE)));
    40→
    41→        // Convert the cache account back into a revm account and mark it as touched.
    42→        let mut revm_acc: revm::state::Account = acc_info.into();
